SELECT id, email, manager_id, job_title, hire_date, is_remote, level, PERCENT_RANK() OVER (PARTITION BY level, job_title ORDER BY salary DESC) AS salary_percent_rank, FIRST_VALUE(job_title, TRUE) OVER (PARTITION BY YEAR(hire_date), job_title ORDER BY hire_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_job_title, NTILE(5) OVER (PARTITION BY MONTH(hire_date), job_title ORDER BY salary DESC, id) AS salary_bucket FROM employees
